<?php	function format_fr($date){		list ($year, $month, $day) = split('-',$date);		if ($day{0}=="0")			$jour = $day{1};		else			$jour = $day;		if ($jour == "1")			$jour = "1&deg;";		if ($month=="01"){$mois = "gennaio";}		if ($month=="02"){$mois = "febbraio";}		if ($month=="03"){$mois = "marzo";}		if ($month=="04"){$mois = "aprile";}		if ($month=="05"){$mois = "maggio";}		if ($month=="06"){$mois = "giugno";}		if ($month=="07"){$mois = "luglio";}		if ($month=="08"){$mois = "agosto";}		if ($month=="09"){$mois = "settembre";}		if ($month=="10"){$mois = "ottobre";}		if ($month=="11"){$mois = "novembre";}		if ($month=="12"){$mois = "dicembre";}		$annee = substr($year, 2, 2);		echo "$jour $mois $annee";	}	function get_format_fr($date){		return format_fr($date);	}?>